module tb;
    // 1. Declare inputs as regs, outputs as wires
    reg clk;
    reg areset;
    reg x;
    wire z;

    // 2. Instantiate TopModule dut
    TopModule dut (
        .clk(clk),
        .areset(areset),
        .x(x),
        .z(z)
    );

    // Clock generation: 10ns period
    always #5 clk = ~clk;

    integer errors = 0;

    // Task to apply input and check expected output on the next clock edge
    task apply_and_check;
        input exp_z;
        input in_x;
        begin
            x = in_x;
            @(posedge clk);
            #1; // Small delay to sample after clock edge
            if (z !== exp_z) begin
                $display("Mismatch: time=%0t | x=%b | expected z=%b, got z=%b", $time, x, exp_z, z);
                errors = errors + 1;
            end
        end
    endtask

    initial begin
        // Initialize signals
        clk = 0;
        areset = 0;
        x = 0;

        // Test asynchronous active-high reset
        areset = 1;
        #12;
        if (z !== 1'b0) begin
            $display("Reset check failed: z is not 0 during reset");
            errors = errors + 1;
        end
        areset = 0;
        #3;

        // 2's complementer state machine test sequence:
        // State A: first '1' encountered gives z=1, then transitions to State B.
        // In State B: all subsequent bits are inverted (z = ~x).

        // From State A:
        // x=0 -> stays A, z=0
        apply_and_check(0, 0);
        // x=0 -> stays A, z=0
        apply_and_check(0, 0);
        // x=1 -> transitions to B, z=1
        apply_and_check(1, 1);

        // Now in State B:
        // x=0 -> stays B, z=1
        apply_and_check(1, 0);
        // x=1 -> stays B, z=0
        apply_and_check(0, 1);
        // x=1 -> stays B, z=0
        apply_and_check(0, 1);
        // x=0 -> stays B, z=1
        apply_and_check(1, 0);

        // Test asynchronous reset recovery back to State A
        areset = 1;
        #7;
        areset = 0;
        #3;

        // Verify we are back in State A
        // x=0 -> stays A, z=0
        apply_and_check(0, 0);
        // x=1 -> transitions to B, z=1
        apply_and_check(1, 1);
        // x=1 -> stays B, z=0
        apply_and_check(0, 1);

        // Final check results
        #10;
        if (errors == 0) begin
            $display("*** TEST RESULT: PASS ***");
        end else begin
            $display("*** TEST RESULT: FAIL ***");
        end
        $finish;
    end

endmodule
